// ── Set operations ────────────────────────────────────────────
const A = new Set([1, 2, 3, 4, 5]);
const B = new Set([3, 4, 5, 6, 7]);

const union        = new Set([...A, ...B]);
const intersection = new Set([...A].filter(x => B.has(x)));
const difference   = new Set([...A].filter(x => !B.has(x)));
const symmetric    = new Set([...union].filter(x => !intersection.has(x)));

console.log('A ∪ B:', [...union]);        // [1,2,3,4,5,6,7]
console.log('A ∩ B:', [...intersection]); // [3,4,5]
console.log('A \ B:', [...difference]);   // [1,2]
console.log('A △ B:', [...symmetric]);    // [1,2,6,7]

// ── Cartesian product ─────────────────────────────────────────
function cartesian(A, B) {
  const result = [];
  for (const a of A)
    for (const b of B)
      result.push([a, b]);
  return result;
}
console.log('A×B (small):', cartesian([1,2], ['x','y']));
// [[1,'x'],[1,'y'],[2,'x'],[2,'y']]

// ── Check function properties ──────────────────────────────────
function isInjective(f, domainArr) {
  const seen = new Set();
  for (const x of domainArr) {
    const fx = f(x);
    if (seen.has(fx)) return false;
    seen.add(fx);
  }
  return true;
}

function isSurjective(f, domainArr, codomainArr) {
  const images = new Set(domainArr.map(f));
  return codomainArr.every(b => images.has(b));
}

const domain   = [1, 2, 3];
const codomain = [2, 4, 6];
const fDouble  = x => x * 2; // maps {1,2,3} → {2,4,6}

console.log('fDouble injective:', isInjective(fDouble, domain));           // true
console.log('fDouble surjective:', isSurjective(fDouble, domain, codomain)); // true
console.log('fDouble bijective:', isInjective(fDouble, domain) &&
  isSurjective(fDouble, domain, codomain)); // true

const fSquare = x => x * x; // maps {-1,0,1} → {0,1} — not injective
console.log('fSquare injective:', isInjective(fSquare, [-1, 0, 1])); // false

// ── Equivalence relation: modular arithmetic ──────────────────
// a ≡ b (mod n)  ↔  n divides (a - b)
// Reflexive:  a ≡ a (mod n)  always
// Symmetric:  a ≡ b → b ≡ a
// Transitive: a ≡ b, b ≡ c → a ≡ c

function modClass(n, mod) {
  return n % mod; // equivalence class representative
}

// Partition {0..11} into classes mod 4
const elements = Array.from({length: 12}, (_, i) => i);
const classes  = {};
for (const x of elements) {
  const cls = modClass(x, 4);
  if (!classes[cls]) classes[cls] = [];
  classes[cls].push(x);
}
console.log('Equivalence classes mod 4:', classes);
// { 0:[0,4,8], 1:[1,5,9], 2:[2,6,10], 3:[3,7,11] }

// ── Composition of functions ──────────────────────────────────
// (g ∘ f)(x) = g(f(x))
const compose = (...fns) => x => fns.reduceRight((acc, fn) => fn(acc), x);

const double = x => x * 2;
const addOne = x => x + 1;
const square = x => x * x;

const transform = compose(square, addOne, double); // square(addOne(double(x)))
console.log('transform(3):', transform(3)); // square(addOne(6)) = square(7) = 49

// ── Power set: subsets of a set ───────────────────────────────
// |P(A)| = 2^|A|
function powerSet(arr) {
  return arr.reduce(
    (subsets, val) => subsets.concat(subsets.map(s => [...s, val])),
    [[]]
  );
}
console.log('P({a,b,c}):', powerSet(['a','b','c']));
// 8 subsets: [], [a], [b], [c], [a,b], [a,c], [b,c], [a,b,c]
